class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        nodes = []
        for head in lists:
            while head:
                nodes.append(head)
                head = head.next
        nodes.sort(key=lambda node: node.val)
        dummy = tail = ListNode()
        for node in nodes:
            tail.next = node
            tail = node
        tail.next = None
        return dummy.next

